class Solution
{
public:
    int closestValue(TreeNode*root, double target)
    {
        int ans = root->val;
        while (root)
        {
            if (abs(root->val - target) < abs(ans - target) || (abs(root->val - target) == abs(ans - target) && root->val < ans))
            {
                ans = root->val;
            }
            root = target < root->val ? root->left : root->right;
        }
        return ans;
    }
};
